//! Cross-platform parity tests.
//!
//! Verifies that the Rust engine produces identical state snapshots
//! for deterministic scenarios. The fixture file is generated by
//! `generate_fixtures.rs` and also consumed by the Kotlin JNA parity
//! tests to ensure cross-platform consistency.

use cribbage_engine::card::Card;
use cribbage_engine::deck::Deck;
use cribbage_engine::game_action::GameAction;
use cribbage_engine::game_engine::GameEngine;
use cribbage_engine::game_stage::GameStage;
use cribbage_engine::game_state::GameState;
use cribbage_engine::player::Player;

const FIXTURE_JSON: &str = include_str!("fixtures/game_scenarios.json");

fn two_players() -> Vec<Player> {
    vec![
        Player::new("p1", "Player 1"),
        Player::new("p2", "Player 2"),
    ]
}

fn play_pegging(engine: &mut GameEngine) {
    for _ in 0..20 {
        let state = engine.current_state();
        if state.stage != GameStage::Pegging {
            break;
        }

        let current_id = state.current_player_id.clone().unwrap();
        let player = state.players.iter().find(|p| p.id == current_id).unwrap();

        let playable: Option<Card> = player
            .hand
            .iter()
            .filter(|c| state.pegging_count + c.pegging_value() as i32 <= 31)
            .min_by_key(|c| c.pegging_value())
            .copied();

        if let Some(card) = playable {
            engine
                .apply_action(GameAction::PlayCard {
                    player_id: current_id,
                    card,
                })
                .unwrap();
        } else {
            engine
                .apply_action(GameAction::Go {
                    player_id: current_id,
                })
                .unwrap();
        }
    }
}

fn assert_state_matches(actual: &GameState, expected: &serde_json::Value, checkpoint: &str) {
    let expected_state: GameState = serde_json::from_value(expected.clone()).unwrap_or_else(|e| {
        panic!("Failed to deserialize expected state at {checkpoint}: {e}");
    });

    assert_eq!(
        actual.stage, expected_state.stage,
        "Stage mismatch at {checkpoint}"
    );
    assert_eq!(
        actual.players.len(),
        expected_state.players.len(),
        "Player count mismatch at {checkpoint}"
    );

    for (i, (actual_p, expected_p)) in actual
        .players
        .iter()
        .zip(expected_state.players.iter())
        .enumerate()
    {
        assert_eq!(
            actual_p.id, expected_p.id,
            "Player {i} ID mismatch at {checkpoint}"
        );
        assert_eq!(
            actual_p.hand.len(),
            expected_p.hand.len(),
            "Player {i} hand size mismatch at {checkpoint}"
        );
        assert_eq!(
            actual_p.score, expected_p.score,
            "Player {i} score mismatch at {checkpoint}"
        );
        assert_eq!(
            actual_p.hand, expected_p.hand,
            "Player {i} hand mismatch at {checkpoint}"
        );
    }

    assert_eq!(
        actual.crib.len(),
        expected_state.crib.len(),
        "Crib size mismatch at {checkpoint}"
    );
    assert_eq!(
        actual.crib, expected_state.crib,
        "Crib contents mismatch at {checkpoint}"
    );
    assert_eq!(
        actual.cut_card, expected_state.cut_card,
        "Cut card mismatch at {checkpoint}"
    );
    assert_eq!(
        actual.pegging_count, expected_state.pegging_count,
        "Pegging count mismatch at {checkpoint}"
    );
    assert_eq!(
        actual.dealer_index, expected_state.dealer_index,
        "Dealer index mismatch at {checkpoint}"
    );
}

#[test]
fn parity_seed_42_full_round() {
    let fixture: serde_json::Value = serde_json::from_str(FIXTURE_JSON).unwrap();
    let scenario = &fixture["scenarios"][0];
    assert_eq!(scenario["name"].as_str().unwrap(), "seed_42_full_round");

    let seed = scenario["seed"].as_u64().unwrap();
    let snapshots = &scenario["snapshots"];

    // Create engine with same seed
    let deck = Deck::with_seed(seed);
    let mut engine = GameEngine::new("parity_test_1", two_players(), Some(deck)).unwrap();

    // Checkpoint: after_deal
    assert_state_matches(
        &engine.current_state(),
        &snapshots["after_deal"],
        "after_deal",
    );

    // Discard first two cards from each player's hand
    let state = engine.current_state();
    let p1_discards: Vec<Card> = state.players[0].hand[..2].to_vec();
    let p2_discards: Vec<Card> = state.players[1].hand[..2].to_vec();

    for card in p1_discards {
        engine
            .apply_action(GameAction::DiscardToCrib {
                player_id: "p1".into(),
                card,
            })
            .unwrap();
    }
    for card in p2_discards {
        engine
            .apply_action(GameAction::DiscardToCrib {
                player_id: "p2".into(),
                card,
            })
            .unwrap();
    }

    // Checkpoint: after_discard
    assert_state_matches(
        &engine.current_state(),
        &snapshots["after_discard"],
        "after_discard",
    );

    // Cut
    let cutter = engine.current_state().current_player_id.clone().unwrap();
    engine
        .apply_action(GameAction::CutDeck {
            player_id: cutter,
        })
        .unwrap();

    // Checkpoint: after_cut
    assert_state_matches(
        &engine.current_state(),
        &snapshots["after_cut"],
        "after_cut",
    );

    // Pegging
    play_pegging(&mut engine);

    // Checkpoint: after_pegging
    assert_state_matches(
        &engine.current_state(),
        &snapshots["after_pegging"],
        "after_pegging",
    );

    // Counting
    for _ in 0..3 {
        let state = engine.current_state();
        if state.stage != GameStage::Counting {
            break;
        }
        let counter = state.current_player_id.clone().unwrap();
        engine
            .apply_action(GameAction::CountHand {
                player_id: counter,
            })
            .unwrap();
    }

    // Checkpoint: after_counting (scores only — new round may reshuffle non-deterministically)
    let expected_scores = &snapshots["after_counting"];
    let final_state = engine.current_state();
    assert_eq!(
        final_state.players[0].score,
        expected_scores["p1_score"].as_i64().unwrap() as i32,
        "P1 final score mismatch"
    );
    assert_eq!(
        final_state.players[1].score,
        expected_scores["p2_score"].as_i64().unwrap() as i32,
        "P2 final score mismatch"
    );
}

/// Verify JSON round-trip: serialize state to JSON, deserialize back, check equality.
#[test]
fn parity_json_round_trip() {
    let fixture: serde_json::Value = serde_json::from_str(FIXTURE_JSON).unwrap();
    let scenario = &fixture["scenarios"][0];
    let snapshots = &scenario["snapshots"];

    // Only test full-state snapshots (not the scores-only after_counting)
    for name in &["after_deal", "after_discard", "after_cut", "after_pegging"] {
        let snap = &snapshots[*name];
        let state: GameState = serde_json::from_value(snap.clone())
            .unwrap_or_else(|e| panic!("Failed to deserialize {name}: {e}"));
        let re_json = serde_json::to_value(&state)
            .unwrap_or_else(|e| panic!("Failed to re-serialize {name}: {e}"));
        let re_state: GameState = serde_json::from_value(re_json)
            .unwrap_or_else(|e| panic!("Failed to re-deserialize {name}: {e}"));

        assert_eq!(
            state.stage, re_state.stage,
            "Round-trip stage mismatch for {name}"
        );
        assert_eq!(
            state.players, re_state.players,
            "Round-trip players mismatch for {name}"
        );
        assert_eq!(
            state.crib, re_state.crib,
            "Round-trip crib mismatch for {name}"
        );
        assert_eq!(
            state.cut_card, re_state.cut_card,
            "Round-trip cut_card mismatch for {name}"
        );
    }
}
